// n8n Code Node (JavaScript)
// Modo: Run Once for All Items

// Função segura para pegar o campo, funcionando antes/depois do Edit Fields
const get = (j, novo, antigo) => j[novo] ?? j[antigo];

const slots = items.map(it => {
  const j = it.json;

  const horaEntrada     = get(j, 'hora-entrada', 'start_text');
  const horaSaida       = get(j, 'hora-saida', 'end_text');

  return {

    texto: `${horaEntrada} às ${horaSaida}`,
  };
});

// Opcional: também gerar uma lista de strings fácil para a IA ler
const textos = slots.map(s => s.texto);

// Retorna UM item com o array completo
return [{
  json: {
    total: slots.length,
    slots,        // array de objetos com datas e horas
    textos        // array de strings "08:00 às 08:30", etc.
  }
}];

// Configurações
const TOL_MIN = 2;          // tolerância (min)
const JAN_2H  = 120;        // 2 horas
const JAN_1H  = 60;         // 1 hora
const JAN_30M = 30;         // 30 minutos

const now = new Date();
const results = [];

for (const item of items) {

  const startRaw = item.json.agendamento;

  if (!startRaw) {
    item.json.diffMinutes = null;
    item.json.in_2h = false;
    item.json.in_1h = false;
    item.json.in_30m = false;
    results.push(item);
    continue;
  }

  const start = new Date(startRaw);
  const diffMs = start - now;
  const diffMinutes = Math.round(diffMs / 60000);

  const in2h  = diffMinutes >= -TOL_MIN && diffMinutes <= (JAN_2H + TOL_MIN);
  const in1h  = Math.abs(diffMinutes - JAN_1H) <= TOL_MIN;
  const in30m = Math.abs(diffMinutes - JAN_30M) <= TOL_MIN;

  item.json.diffMinutes = diffMinutes;
  item.json.in_2h  = in2h;
  item.json.in_1h  = in1h;
  item.json.in_30m = in30m;

  results.push(item);
}

return results;

// Mode: Run Once for All Items

const LIMITE_2H = 120;  // 2 horas
const ALVO_30M  = 30;   // alvo 30 min
const TOL_MIN   = 5;    // tolerância 25–35 min

// array final apenas com quem deve receber aviso
const output = [];

for (const item of items) {
  const j = item.json || {};

  const raw = j["Data da agenda"];   // exemplo: "24/11/2025 10:00"
  const horaAtualStr = j["hora_atual"]; // exemplo: "08:34:50"

  if (!raw || !horaAtualStr) {
    j.aviso2h = false;
    j.aviso30m = false;
    continue;
  }

  // separa data e hora do agendamento
  const [dataStr, horaStr] = raw.split(" ");
  const [dia, mes, ano] = dataStr.split("/").map(Number);
  const [hh, mm] = horaStr.split(":").map(Number);

  // monta DATE do horário do agendamento
  const start = new Date(ano, mes - 1, dia, hh, mm, 0);

  // hora local atual do cliente
  const [hNow, mNow, sNow] = horaAtualStr.split(":").map(Number);
  const now = new Date(ano, mes - 1, dia, hNow, mNow, sNow || 0);

  // diferença em minutos
  const diffMin = (start.getTime() - now.getTime()) / 60000;

  // verifica janelas
  const dentro2h = diffMin >= 0 && diffMin <= LIMITE_2H;
  const dentro30m = diffMin >= (ALVO_30M - TOL_MIN) &&
                    diffMin <= (ALVO_30M + TOL_MIN);

  // flags iniciais
  let aviso2h = false;
  let aviso30m = false;

  // prioridade: 30 minutos > 2 horas
  if (dentro30m) {
    aviso30m = true;
  } else if (dentro2h) {
    aviso2h = true;
  }

  // salvar no JSON para debug
  j.diffMin = Number(diffMin.toFixed(2));
  j.aviso2h = aviso2h;
  j.aviso30m = aviso30m;

  // só envia para o output quem realmente deve receber aviso
  if (aviso2h || aviso30m) {
    output.push(item);
  }
}

// retorna APENAS os itens que precisam de aviso
return output;

