// Gera um atraso aleatório entre 20s e 80s para CADA item
const MIN_S = 60;      // 20 segundos
const MAX_S = 300;      // 1 min 20s

for (const item of items) {
  const s = Math.floor(MIN_S + Math.random() * (MAX_S - MIN_S + 1));
  item.json.delaySeconds = s;        // ex.: 37
  item.json.delayMs = s * 1000;      // ex.: 37000
  item.json.delayHuman = `${s}s`;    // útil para logs/debug
}

return items;

for (const item of $input.all()) {

  const raw = item.json["Número do telefone"] ?? item.json.numero ?? "";

  // Remove tudo que não for número
  let digits = String(raw).replace(/\D/g, "");

  // Garante que começa com 55
  if (!digits.startsWith("55")) {
    digits = "55" + digits;
  }

  // Remove o 55 para tratar separado
  let body = digits.slice(2);

  // Pega DDD
  const ddd = body.slice(0, 2);

  // Pega número
  let numero = body.slice(2);

  // 🔥 REGRA DO 9 EXTRA
  if (numero.length === 9 && numero.startsWith("9")) {
    numero = numero.slice(1);
  }

  const finalNumber = "55" + ddd + numero + "@s.whatsapp.net";

  item.json.numero_formatado = finalNumber;
}

return $input.all();

for (const item of $input.all()) {
  const dataTexto = item.json["Último atendimento"];
  if (!dataTexto) {
    item.json.passou_60_dias = false;
    continue;
  }
  // separa data e hora
  const [dataParte] = dataTexto.split(" ");
  const [dia, mes, ano] = dataParte.split("/").map(Number);
  // cria objeto Date corretamente
  const dataUltimo = new Date(ano, mes - 1, dia);
  const hoje = new Date();
  // calcula diferença em dias
  const diffDias = Math.floor((hoje - dataUltimo) / (1000 * 60 * 60 * 24));
  item.json.passou_60_dias = diffDias >= 60;
}
return $input.all();

